package com.coffeeshop.repository;
import com.coffeeshop.dto.TableManagementCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.TableManagementModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;
public final class JdbcTableManagementRepository implements TableManagementRepository{private final DataSource ds;public JdbcTableManagementRepository(DataSource d){ds=Objects.requireNonNull(d);}public List<TableManagementModels.CafeTable>tables(){String q="SELECT cafe_table_id,table_code,table_name,capacity,status,display_order,is_active,row_version FROM dbo.cafe_tables ORDER BY display_order,table_name";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<TableManagementModels.CafeTable>x=new ArrayList<>();while(r.next())x.add(new TableManagementModels.CafeTable(r.getLong(1),r.getString(2),r.getString(3),r.getInt(4),r.getString(5),r.getInt(6),r.getBoolean(7),r.getBytes(8)));return List.copyOf(x);}catch(SQLException e){throw fail("Unable to load cafe tables.",e);}}public List<TableManagementModels.Reservation>reservations(){String q="SELECT tr.table_reservation_id,tr.reservation_number,tr.cafe_table_id,t.table_name,tr.customer_id,tr.guest_name,tr.contact_phone,tr.contact_email,tr.reservation_start_at,tr.party_size,tr.status,tr.notes,tr.row_version FROM dbo.table_reservations tr JOIN dbo.cafe_tables t ON t.cafe_table_id=tr.cafe_table_id ORDER BY tr.reservation_start_at DESC";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<TableManagementModels.Reservation>x=new ArrayList<>();while(r.next()){long customer=r.getLong(5);x.add(new TableManagementModels.Reservation(r.getLong(1),r.getString(2),r.getLong(3),r.getString(4),r.wasNull()?null:customer,r.getString(6),r.getString(7),r.getString(8),r.getTimestamp(9).toLocalDateTime(),r.getInt(10),r.getString(11),r.getString(12),r.getBytes(13)));}return List.copyOf(x);}catch(SQLException e){throw fail("Unable to load reservations.",e);}}public long saveTable(TableManagementCommands.SaveTable q){String sql=q.id()==null?"INSERT dbo.cafe_tables(table_code,table_name,capacity,status,display_order,is_active) VALUES(?,?,?,?,?,?)":"UPDATE dbo.cafe_tables SET table_code=?,table_name=?,capacity=?,status=?,display_order=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE cafe_table_id=? AND row_version=?";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){s.setString(1,q.code());s.setString(2,q.name());s.setInt(3,q.capacity());s.setString(4,q.status());s.setInt(5,q.displayOrder());s.setBoolean(6,q.active());if(q.id()!=null){s.setLong(7,q.id());s.setBytes(8,q.rowVersion());one(s.executeUpdate());return q.id();}s.executeUpdate();return key(s);}catch(SQLException e){throw fail("Unable to save the cafe table. Check that its code is unique.",e);}}public void setTableActive(long id,boolean active,byte[] version){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("UPDATE dbo.cafe_tables SET is_active=?,updated_at=SYSUTCDATETIME() WHERE cafe_table_id=? AND row_version=?")){s.setBoolean(1,active);s.setLong(2,id);s.setBytes(3,version);one(s.executeUpdate());}catch(SQLException e){throw fail("Unable to update the table.",e);}}public long saveReservation(TableManagementCommands.SaveReservation q){try(Connection c=ds.getConnection()){c.setAutoCommit(false);try{String number=q.id()==null?number(c):null;String sql=q.id()==null?"INSERT dbo.table_reservations(reservation_number,cafe_table_id,customer_id,guest_name,contact_phone,contact_email,reservation_start_at,party_size,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?)":"UPDATE dbo.table_reservations SET cafe_table_id=?,customer_id=?,guest_name=?,contact_phone=?,contact_email=?,reservation_start_at=?,party_size=?,status=?,notes=?,updated_at=SYSUTCDATETIME() WHERE table_reservation_id=? AND row_version=?";long id;try(PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){int i=1;if(q.id()==null)s.setString(i++,number);s.setLong(i++,q.tableId());nullableLong(s,i++,q.customerId());s.setString(i++,q.guestName());nullable(s,i++,q.phone());nullable(s,i++,q.email());s.setTimestamp(i++,Timestamp.valueOf(q.startsAt()));s.setInt(i++,q.partySize());s.setString(i++,q.status());nullable(s,i++,q.notes());if(q.id()!=null){s.setLong(i++,q.id());s.setBytes(i,q.rowVersion());one(s.executeUpdate());id=q.id();}else{s.executeUpdate();id=key(s);}}c.commit();return id;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to save the reservation.",e);}}private static String number(Connection c)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT setting_value FROM dbo.settings WHERE setting_key='numbering.reservation.prefix'");ResultSet r=s.executeQuery()){String p=r.next()?r.getString(1):"RSV";try(PreparedStatement n=c.prepareStatement("SELECT NEXT VALUE FOR dbo.seq_reservation_number");ResultSet x=n.executeQuery()){x.next();return p+String.format("%08d",x.getLong(1));}}}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static void nullableLong(PreparedStatement s,int i,Long v)throws SQLException{if(v==null)s.setNull(i,Types.BIGINT);else s.setLong(i,v);}private static void one(int n){if(n!=1)throw new IllegalStateException("This record changed. Refresh and try again.");}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated identifier unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
